import { NextResponse } from "next/server"
import { readSnapshot } from "@/lib/report"

// Force static rendering — the snapshot file is checked into the repo
// and only regenerated by a script, so we want the bundle to bake the
// response. Edge-cache headers act as a belt-and-braces.
export const dynamic = "force-static"
export const revalidate = 86400 // 24h

export async function GET() {
  try {
    const snapshot = await readSnapshot()
    return NextResponse.json(snapshot, {
      headers: {
        "Cache-Control":
          "public, s-maxage=86400, stale-while-revalidate=604800",
      },
    })
  } catch (err) {
    console.error("[/api/report/snapshot] failed to load snapshot:", err)
    return NextResponse.json(
      { error: "snapshot unavailable" },
      { status: 500 },
    )
  }
}
